@Component("verifiedAddress-handler")
@ProcessingGroup("verifiedAddress-processing-group")
public class VerifiedAddressEventHandler {
	
	// core constructor
	VerifiedAddressEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateVerifiedAddressEvent
     */
    @EventHandler
    public void handle( CreateVerifiedAddressEvent event) {
        entityManager.persist(new VerifiedAddress(event.getVerifiedAddressId(), event.getAddress(), event.getVerifiedAt(), event.getKycProfile(), event.getVerificationStatus()));
    }

    /*
     * @param	event UpdateVerifiedAddressEvent
     */
    @EventHandler
    public VerifiedAddress handle( UpdateVerifiedAddressEvent event) {
    	entityManager.merge(new VerifiedAddress(event.getVerifiedAddressId(), event.getAddress(), event.getVerifiedAt(), event.getKycProfile(), event.getVerificationStatus()));
    }
    
    /*
     * @param	event DeleteVerifiedAddressEvent
     */
    @EventHandler
    public void on( DeleteVerifiedAddressEvent event) {
    	VerifiedAddress entity = new VerifiedAddress();
   
    	// ------------------------------------------
    	// apply the VerifiedAddressId
    	// ------------------------------------------
    	entity.setVerifiedAddressId( event.getVerifiedAddressId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final VerifiedAddressRepository verifiedAddressEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(VerifiedAddressEventHandler.class.getName());

}
